script:
(function () {
  'use strict';
  // Emergency fund: target = essential monthly expenses x months to cover + one-off costs.
  // Time to goal: month by month, balance = balance x (1 + i) + monthly saving (end of month),
  // with i = (1 + APY)^(1/12) - 1. Counts whole months until the balance reaches the target.
  // Payment to finish in 12 months: P = (target - saved (1+i)^12) x i / ((1+i)^12 - 1), or
  // (target - saved) / 12 when i = 0.
  // Checks: $3,500 x 6 = $21,000 target; from $3,000 at $400/month and 0% it takes
  // 18,000 / 400 = 45 months; at 3% APY the closed form n = ln((FV i + P)/(PV i + P)) / ln(1+i)
  // gives 41.99 -> 42 months, matching the month-by-month loop; the 12-month payment
  // at 3% ($1,472.36) grows $3,000 to exactly $21,000 in 12 months.
  var money = new Intl.NumberFormat('en-US', { style: 'currency', currency: 'USD', minimumFractionDigits: 2, maximumFractionDigits: 2 });
  var money0 = new Intl.NumberFormat('en-US', { style: 'currency', currency: 'USD', maximumFractionDigits: 0 });
  var monthName = new Intl.DateTimeFormat('en-US', { month: 'short', year: 'numeric' });
  var EXPENSES = ['esHousing', 'esUtilities', 'esFood', 'esTransport', 'esInsurance', 'esDebt', 'esOther'];
  var MAX_MONTHS = 600;

  function num(id) {
    var raw = document.getElementById(id).value;
    if (raw === '') return 0;
    var v = parseFloat(raw);
    return isNaN(v) ? NaN : v;
  }

  // Months until balance >= each target in targets (ascending); -1 if not reached within MAX_MONTHS.
  function monthsToTargets(saved, monthly, apy, targets) {
    var i = Math.pow(1 + apy, 1 / 12) - 1, balance = saved, deposits = saved, out = [], k = 0;
    while (k < targets.length && balance >= targets[k] - 0.005) { out.push({ months: 0, interest: 0 }); k++; }
    for (var m = 1; m <= MAX_MONTHS && k < targets.length; m++) {
      balance = balance * (1 + i) + monthly;
      deposits += monthly;
      while (k < targets.length && balance >= targets[k] - 0.005) { out.push({ months: m, interest: balance - deposits }); k++; }
    }
    while (k < targets.length) { out.push({ months: -1, interest: 0 }); k++; }
    return out;
  }

  function paymentFor(target, saved, apy, months) {
    var i = Math.pow(1 + apy, 1 / 12) - 1;
    var p = i === 0 ? (target - saved) / months : (target - saved * Math.pow(1 + i, months)) * i / (Math.pow(1 + i, months) - 1);
    return Math.max(0, p);
  }

  function duration(months) {
    var y = Math.floor(months / 12), m = months % 12, parts = [];
    if (y) parts.push(y + (y === 1 ? ' year' : ' years'));
    if (m || !y) parts.push(m + (m === 1 ? ' month' : ' months'));
    return parts.join(' ');
  }

  function dateAfter(months) {
    var now = new Date();
    return monthName.format(new Date(now.getFullYear(), now.getMonth() + months, 1));
  }

  function set(id, text) { document.getElementById(id).textContent = text; }

  function clear(id) {
    var el = document.getElementById(id);
    while (el.firstChild) el.removeChild(el.firstChild);
    return el;
  }

  function addRow(body, cells) {
    var tr = document.createElement('tr');
    cells.forEach(function (text) {
      var td = document.createElement('td');
      td.textContent = text;
      tr.appendChild(td);
    });
    body.appendChild(tr);
  }

  function blank() {
    ['esTarget', 'esNeed', 'esTime', 'esCover', 'esProgress', 'esIn12', 'esInterest'].forEach(function (id) { set(id, '–'); });
    set('esDate', '');
    document.getElementById('esWarn').hidden = true;
    clear('esMilestones');
  }

  function update() {
    var expense = 0, badExpense = false;
    EXPENSES.forEach(function (id) {
      var v = num(id);
      if (isNaN(v) || v < 0) badExpense = true; else expense += v;
    });
    set('esExpenseTotal', badExpense ? '–' : money.format(expense));
    var months = num('esMonths'), saved = num('esSaved'), monthly = num('esMonthly'), apy = num('esApy'), extra = num('esExtra');
    var msg = '';
    if (badExpense) msg = 'Enter each expense as $0 or more.';
    else if (expense > 1e9) msg = 'Enter smaller expense amounts.';
    else if (isNaN(months) || months < 1 || months > 24 || Math.round(months) !== months) msg = 'Enter 1 to 24 whole months of expenses to cover.';
    else if (isNaN(saved) || saved < 0 || saved > 1e10) msg = 'Enter the amount saved so far as $0 or more.';
    else if (isNaN(monthly) || monthly < 0 || monthly > 1e9) msg = 'Enter a monthly saving of $0 or more.';
    else if (isNaN(apy) || apy < 0 || apy > 20) msg = 'Enter a savings APY from 0 to 20%.';
    else if (isNaN(extra) || extra < 0 || extra > 1e9) msg = 'Enter one-off costs of $0 or more.';
    else if (expense + extra <= 0) msg = 'Enter at least one monthly expense or one-off cost.';
    var error = document.getElementById('esError');
    error.hidden = !msg;
    if (msg) { error.textContent = msg; blank(); return; }

    var target = expense * months + extra;
    var need = Math.max(0, target - saved);
    var r = apy / 100;
    set('esTarget', money0.format(target));
    set('esNeed', money0.format(need));
    set('esCover', expense > 0 ? (saved / expense).toFixed(1) + ' months' : '–');
    set('esProgress', Math.min(100, saved / target * 100).toFixed(0) + '%');
    set('esIn12', money.format(paymentFor(target, saved, r, 12)));

    var steps = [1, 2, 3, 6, 9, 12, 18].filter(function (s) { return s < months && expense > 0; });
    var marks = steps.map(function (s) { return { label: s + (s === 1 ? ' month' : ' months') + ' of expenses', amount: expense * s }; });
    marks.push({ label: 'Your target (' + months + (months === 1 ? ' month' : ' months') + (extra > 0 ? ' + one-off costs' : '') + ')', amount: target });
    var hits = monthsToTargets(saved, monthly, r, marks.map(function (x) { return x.amount; }));
    var goal = hits[hits.length - 1];
    var warn = document.getElementById('esWarn');
    warn.hidden = true;
    if (goal.months === 0) {
      set('esTime', 'Reached');
      set('esDate', 'Your savings already cover the target');
      set('esInterest', money.format(0));
    } else if (goal.months < 0) {
      set('esTime', monthly > 0 || r > 0 ? 'Over 50 years' : 'Never');
      set('esDate', 'At this monthly saving');
      set('esInterest', '–');
      warn.textContent = 'At ' + money.format(monthly) + ' a month you will not reach the target within 50 years. Saving ' + money.format(paymentFor(target, saved, r, 12)) + ' a month would get you there in a year.';
      warn.hidden = false;
    } else {
      set('esTime', duration(goal.months));
      set('esDate', 'Around ' + dateAfter(goal.months));
      set('esInterest', money.format(goal.interest));
    }

    var body = clear('esMilestones');
    marks.forEach(function (mk, idx) {
      var h = hits[idx];
      var when = h.months === 0 ? 'Already reached' : h.months < 0 ? 'Over 50 years' : duration(h.months);
      var date = h.months === 0 ? 'Now' : h.months < 0 ? '–' : dateAfter(h.months);
      addRow(body, [mk.label, money0.format(mk.amount), when, date]);
    });
  }

  document.addEventListener('DOMContentLoaded', function () {
    var form = document.getElementById('esForm');
    form.addEventListener('input', update);
    form.addEventListener('change', update);
    form.addEventListener('submit', function (e) { e.preventDefault(); });
    update();
  });
})();
